import test from 'node:test';
import assert from 'node:assert/strict';
import {processorFixture,latest} from './sarin-whatsapp-processor-fixture.mjs';
import {processWhatsAppWork} from '../../server/sarin/whatsapp/processor.js';
import {createYCloudClient} from '../../server/sarin/whatsapp/ycloud-client.js';
async function setup(t){const f=await processorFixture(t);await processWhatsAppWork(await f.capture(),f.env,{store:f.store,now:f.now,fetch:f.fetch});const o=latest(f,'sarin_wa_outbox');return {...f,outboxId:o.outbox_id,providerId:o.provider_id};}
const request=f=>{assert.equal(typeof f.store.requestReconciliation,'function','Falta solicitud durable');return f.store.requestReconciliation({outboxId:f.outboxId,actor:'staff_test'});};
const claim=f=>f.store.claimReconciliation({token:crypto.randomUUID(),recipient:{wabaId:'12345',from:'+573000000002',to:'+573000000001'}});
test('lookup_requests_coalesce_and_three_attempts_are_lifetime',async t=>{const f=await setup(t);await request(f);for(let n=1;n<=3;n++){const token=crypto.randomUUID(),c=await f.store.claimReconciliation({token,recipient:{wabaId:'12345',from:'+573000000002',to:'+573000000001'}});assert.equal(c.permit.attempt,n);await request(f);assert.equal((await claim(f)).status,'none');const r=await f.store.finishReconciliation({outboxId:f.outboxId,token,result:{kind:'unavailable',code:'provider_rejected'}});assert.equal(r.status,n===3?'exhausted':'pending');if(n<3){await request(f);f.setTime(f.now()+59999);assert.equal((await claim(f)).status,'none');f.setTime(f.now()+1);}}await request(f);f.setTime(f.now()+120000);assert.equal((await claim(f)).status,'none');assert.equal(latest(f,'sarin_wa_outbox').state,'accepted');});
test('lookup_expired_claim_consumes_attempt_and_waits_after_lease',async t=>{const f=await setup(t);await request(f);await claim(f);f.setTime(f.now()+120000);await f.store.expireReconciliationLeases();assert.equal((await claim(f)).status,'none');await request(f);f.setTime(f.now()+59999);assert.equal((await claim(f)).status,'none');f.setTime(f.now()+1);assert.equal((await claim(f)).permit.attempt,2);});
test('lookup_uses_monotonic_reducer_and_stale_token_cannot_apply',async t=>{const f=await setup(t);await request(f);const token=crypto.randomUUID();await f.store.claimReconciliation({token,recipient:{wabaId:'12345',from:'+573000000002',to:'+573000000001'}});await assert.rejects(f.store.finishReconciliation({outboxId:f.outboxId,token:crypto.randomUUID(),result:{kind:'observation',observation:{providerId:f.providerId,status:'delivered',at:f.now()}}}));assert.equal(latest(f,'sarin_wa_outbox').delivered_at,null);await f.pause();const r=await f.store.finishReconciliation({outboxId:f.outboxId,token,result:{kind:'observation',observation:{providerId:f.providerId,status:'read',at:f.now()}}});assert.equal(r.status,'complete');assert.equal(latest(f,'sarin_wa_outbox').state,'read');assert.equal(latest(f,'sarin_wa_contexts').paused,1);});
test('lookup_denies_missing_id_expired_and_mismatched_recipient',async t=>{const f=await setup(t);await request(f);assert.equal((await f.store.claimReconciliation({token:crypto.randomUUID(),recipient:{wabaId:'12345',from:'+573000000002',to:'+573000000003'}})).status,'none');f.setTime(f.now()+86400001);await assert.rejects(request(f),e=>e.code==='work_denied');assert.equal((await claim(f)).status,'none');});
test('lookup_identity_conflict_closes_polling_and_preserves_delivery',async t=>{const f=await setup(t);await request(f);const token=crypto.randomUUID();await f.store.claimReconciliation({token,recipient:{wabaId:'12345',from:'+573000000002',to:'+573000000001'}});const r=await f.store.finishReconciliation({outboxId:f.outboxId,token,result:{kind:'identity_conflict'}});assert.equal(r.status,'conflict');assert.equal(latest(f,'sarin_wa_outbox').conflict,1);await request(f);assert.equal((await claim(f)).status,'none');});
for(const field of ['id','wabaId','from','to','externalId'])test('GET_rejects_supplied_conflicting_'+field,async()=>{const expected={wabaId:'12345',from:'+573000000002',to:'+573000000001',externalId:crypto.randomUUID()};const client=createYCloudClient({apiKey:'synthetic',businessPhone:expected.from,fetcher:async()=>Response.json({id:'provider',status:'delivered',...expected,[field]:field==='from'||field==='to'?'+573000000099':'different'})});await assert.rejects(client.getMessage({id:'provider',expected}),e=>e.code==='identity_conflict');});
test('GET_preserves_optional_identity_and_accepts_pending',async()=>{const expected={wabaId:'12345',from:'+573000000002',to:'+573000000001',externalId:crypto.randomUUID()};const client=createYCloudClient({apiKey:'synthetic',businessPhone:expected.from,fetcher:async()=>Response.json({id:'provider',status:'queued',...expected})});const result=await client.getMessage({id:'provider',expected});assert.equal(result.status,'pending');for(const k of Object.keys(expected))assert.equal(result[k],expected[k]);});
test('webhook_definitive_result_closes_pending_lookup_and_invalidates_claim',async t=>{const f=await setup(t);await request(f);const token=crypto.randomUUID();await f.store.claimReconciliation({token,recipient:{wabaId:'12345',from:'+573000000002',to:'+573000000001'}});await f.store.applyStatus({eventId:'late_webhook',providerId:f.providerId,status:'delivered',at:f.now()});assert.equal(latest(f,'sarin_wa_outbox').reconcile_state,'complete');assert.equal(latest(f,'sarin_wa_outbox').reconcile_token,null);await assert.rejects(f.store.finishReconciliation({outboxId:f.outboxId,token,result:{kind:'pending'}}));assert.equal(latest(f,'sarin_wa_outbox').reconcile_attempts,1);});
test('restore_floor_blocks_claim_and_stale_finish_without_refund',async t=>{const f=await setup(t);await request(f);const token=crypto.randomUUID();await f.store.claimReconciliation({token,recipient:{wabaId:'12345',from:'+573000000002',to:'+573000000001'}});f.sqlite.prepare('UPDATE sarin_wa_state SET replay_floor_at=? WHERE id=1').run(f.now()+1);await assert.rejects(f.store.finishReconciliation({outboxId:f.outboxId,token,result:{kind:'pending'}}));f.setTime(f.now()+180001);await f.store.expireReconciliationLeases();assert.equal((await claim(f)).status,'none');assert.equal(latest(f,'sarin_wa_outbox').reconcile_attempts,1);});
test('staff_projection_exposes_lookup_availability_without_provider_secret_or_id',async t=>{const f=await setup(t);let peer=await f.store.getPeer({peerKey:f.peerKey});assert.equal(peer.outputs[0].reconcile_available,1);assert.equal('provider_id' in peer.outputs[0],false);await f.store.applyStatus({eventId:'projection_delivery',providerId:f.providerId,status:'delivered',at:f.now()});peer=await f.store.getPeer({peerKey:f.peerKey});assert.equal(peer.outputs[0].reconcile_available,0);assert.equal(peer.outputs[0].reconcile_state,'complete');});
